#include "asset_cache.hpp"
#include <unordered_map>
#include <stdexcept>
#include <utility>
// 구현 파일만 컨테이너 정의를 포함하여 헤더 의존성을 제한한다.
struct AssetCache::Impl {
  std::unordered_map < std::string, int > entries;
};
AssetCache::AssetCache() : impl_(std::make_unique < Impl >()) {
}
AssetCache::~ AssetCache() = default;
AssetCache::AssetCache(AssetCache &&) noexcept = default;
AssetCache & AssetCache::operator =(AssetCache &&) noexcept = default;
bool AssetCache::Add(std::string key, int value) {
  // 도메인 오류를 먼저 검사하므로 기존 맵을 건드리지 않는다.
  if (key.empty() || value < 0) throw std::invalid_argument("invalid asset");
  if (! impl_) impl_ = std::make_unique < Impl >();
  // 이동 후 재사용 계약
  // 이미 있는 키는 값을 덮어쓰지 않는 삽입 정책이다.
  return impl_->entries.try_emplace(std::move(key), value).second;
}
int AssetCache::Find(const std::string & key) const {
  if (! impl_) return - 1;
  const auto it = impl_->entries.find(key);
  return it == impl_->entries.end() ? - 1 : it->second;
}
std::size_t AssetCache::Size() const noexcept {
  return impl_ ? impl_->entries.size() : 0;
}

#pragma once
#include <memory>
#include <string>
#include <cstddef>
class AssetCache {
  struct Impl;
  std::unique_ptr < Impl > impl_;
  public : AssetCache();
  ~ AssetCache();
  // 불완전한 Impl의 삭제는 정의가 보이는 cpp에서 수행한다.
  AssetCache(AssetCache &&) noexcept;
  AssetCache & operator =(AssetCache &&) noexcept;
  AssetCache(const AssetCache &) = delete;
  AssetCache & operator =(const AssetCache &) = delete;
  bool Add(std::string key, int value);
  int Find(const std::string & key) const;
  std::size_t Size() const noexcept;
};

#include "asset_cache.hpp"
#include <iostream>
#include <stdexcept>
#include <type_traits>
#include <utility>
int checks = 0;
void Check(bool b, const char * w) {
  ++ checks;
  if (! b) throw std::runtime_error(w);
}
int main() {
  // 빈 캐시에서 시작해 중복 삽입과 조회 정책을 확인한다.
  AssetCache cache;
  Check(cache.Size() == 0, "empty");
  Check(cache.Add("hero", 4), "first insert");
  Check(! cache.Add("hero", 9), "duplicate keeps original");
  Check(cache.Find("hero") == 4 && cache.Size() == 1, "map invariant");
  Check(cache.Find("none") == - 1, "missing key");
  // 실패한 값은 기존 원소 수를 바꾸지 않아야 한다.
  bool rejected = false;
  try {
    cache.Add("bad", - 1);
  } catch (const std::invalid_argument &) {
    rejected = true;
  }
  Check(rejected && cache.Size() == 1, "validation before mutation");
  // 이동 후 원본의 허용 연산도 클래스 계약으로 검사한다.
  AssetCache moved(std::move(cache));
  Check(moved.Find("hero") == 4, "pimpl moved");
  Check(cache.Size() == 0, "moved-from query contract");
  Check(cache.Add("rebuilt", 2), "moved-from object reusable");
  // 복사 불가와 예외 없는 이동은 컴파일 시점의 별도 검사다.
  static_assert(! std::is_copy_constructible_v < AssetCache >);
  static_assert(std::is_nothrow_move_constructible_v < AssetCache >);
  std::cout << "integration: explicit ownership and narrow build boundary\nPASS: " << checks << " checks\n";
}
